import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via ctx.textureLoader (cached, synchronous)
  const texture = ctx.textureLoader.load(config.assetImageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry for the card
  const geometry = new THREE.PlaneGeometry(1, 1);

  // MeshBasicMaterial for static, unlit composition
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position, rotation, scale from config
  const scenePos = config.scenePosition || {};
  const x = scenePos.x ?? 0;
  const y = scenePos.y ?? 0;
  const z = scenePos.z ?? 0;
  const [rx, ry, rz] = scenePos.rotationXYZ || [0, 0, 0];
  const [sx, sy, sz] = scenePos.scaleXYZ || [1, 1, 1];

  mesh.position.set(x, y, z);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.x = rx;
  mesh.rotation.y = ry;
  mesh.rotation.z = rz;
  mesh.scale.set(sx, sy, sz);

  group.add(mesh);

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Event handlers
  group.userData.handlers = {};

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
